mapper.select:
SELECT 
  FROM emp11_reward
  JOIN emp01_person ON emp11_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp11_person_id  = #{personId}
 ORDER BY emp11_reward_dt DESC

mapper.update:
UPDATE emp11_reward
   SET emp11_reward_cd    = #{req.rewardCd}
     , emp11_reward_dt    = #{req.rewardDt}::date
     , emp11_reward_group = #{req.rewardGroup}
     , emp11_reward_nm    = #{req.rewardNm}
     , emp11_reward_desc  = #{req.rewardDesc}
     , emp11_note         = #{req.note}
 WHERE emp11_reward_id = #{rewardId}
   AND emp11_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
DELETE FROM emp11_reward
 WHERE emp11_reward_id IN
#{id}
   AND emp11_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )
